        assert.equal(r.source, 'quality workflow');
    });

    test('a commented-out setup-dart step does not hijack detection', function () {
        var r = dsRun('plan', { qualityYml: DS_QUALITY_COMMENTED_STEP });
        assert.equal(r.channel, 'stable',
